  while (!ctx->play_stop && ctx->playing)
    {
      /* 模拟播放 */

      usleep(ctx->config.frame_ms * 1000);
    }

  /* 播放完成回调 */

  if (ctx->play_cb)
    {
      ctx->play_cb(ctx->play_user_data);
    }

  AUDIO_DEBUG("播放线程退出");
  return NULL;
}

