/**
 * @brief  解析API响应
 */

static int llm_parse_api_response(llm_context_t *ctx,
                                  llm_response_t *http_response,
                                  char *content, size_t content_size)
{
  if (ctx == NULL || http_response == NULL || content == NULL)
