 */

void sound_detect_set_threshold(sound_detect_context_t *ctx,
                                float threshold)
{
  if (ctx == NULL)
    {
      return;
    }

  SOUND_DEBUG("设置检测阈值: %.2f", threshold);

  ctx->config.threshold = threshold;

  /* 更新各分类阈值 */

  for (int i = 0; i < SOUND_TYPE_MAX; i++)
    {
      ctx->classes[i].threshold = threshold;
    }
}

