/****************************************************************************
 * AI Care Module Header
 * 智爱陪伴 - AI老人陪伴守护终端
 * 主动关怀模块 - 定时问候、健康提醒、生活提醒
 ****************************************************************************/

#ifndef __AI_CARE_H
#define __AI_CARE_H

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
